// #3608cf /users (ADMIN) на 390 px: страница = ширине экрана, таблица прокручивается внутри .table-wrap, «עריכה» достижима, окно помещается.
// Кейсы: .qa/tests/mobile-tables/MT-01. План: specs/mobile-tables.md. Только чтение: окно редактирования открываем и закрываем «ביטול».
import { test, expect } from '@playwright/test';
import { authFile, MOBILE_VIEWPORT, tableWraps, expectPageFits, expectScrollsInsideWrap, expectReachable, expectDialogFits, cancelDialog, dialog } from './helpers';

test.use({ storageState: authFile('admin'), viewport: MOBILE_VIEWPORT });

test.describe('משתמשי החברה במובייל 390px', () => {
  test('/users: הדף לא גולש לרוחב והטבלה נגללת בתוך המכל #3608cf @mobile @prod-safe', async ({ page }) => {
    // MT-01
    await page.goto('/users');
    await expect(page.getByRole('heading', { name: 'משתמשי החברה', level: 1 })).toBeVisible();
    const wrap = tableWraps(page).first();
    await expect(wrap.getByRole('row').nth(1)).toBeVisible();
    await expectPageFits(page, '/users после загрузки');
    await expectScrollsInsideWrap(wrap, 'таблица пользователей');
  });

  test('/users: "עריכה" נגישה בכל שורה והחלון נכנס למסך #3608cf @mobile @prod-safe', async ({ page }) => {
    // MT-01
    await page.goto('/users');
    const wrap = tableWraps(page).first();
    const rows = wrap.locator('tbody tr');
    await expect(rows.first()).toBeVisible();
    const n = await rows.count();
    for (let i = 0; i < n; i++) {
      await expectReachable(page, rows.nth(i).getByRole('button', { name: 'עריכה' }).first(), `строка ${i + 1}: «עריכה»`);
    }
    await rows.first().getByRole('button', { name: 'עריכה' }).first().click();
    await expectDialogFits(page, 'окно «עריכת פרטי משתמש»');
    await expect(dialog(page).first().getByRole('button', { name: 'שמירה', exact: true })).toBeVisible();
    await cancelDialog(page);
    await expect(page).toHaveURL(/\/users$/);
    await expectPageFits(page, '/users после «ביטול»');
  });
});
